from bagimlilik.bagimlilik import kurulum_sirasi, DonguHatasi

# Test 1: Basit doğrusal sıralama
deps1 = {"B": ["A"], "C": ["B"]}
sira1 = kurulum_sirasi(deps1)
print(f"Test 1 (A->B->C): {ira1}") # Beklenen: ['A', 'B', 'C']

# Test 2: Alfabetik öncelik (A ve C bağımsız)
deps2 = {"A": [], "C": []}
sira2 = kurulum_sirasi(deps2)
print(f"Test 2 (A, C): {sira2}") # Beklenen: ['A', 'C']

# Test 3: Karmaşık ve alfabetik öncelik (A ve B bağımsız)
deps3 = {"C": ["A", "B"], "A": [], "B": []}
sira3 = kurulum_sirasi(deps3)
print(f"Test 3 (A, B -> C): {sira3}") # Beklenen: ['A', 'B', 'C']

# Test 4: Döngü (A->B->A)
deps4 = {"A": ["B"], "B": ["A"]}
try:
    kurulum_sirasi(deps4)
except DonguHatasi as e:
    print(f"Test 4 (Döngü A-B): Başarılı. Döngü: {e.dongu}") # Beklenen: ['A', 'B']

# Test 5: Tek elemanlı döngü (X->X)
deps5 = {"X": ["X"]}
try:
    kurulum_sirasi(deps5)
except DonguHatasi as e:
    print(f"Test 5 (Döngü X-X): Başarılı. Döngü: {e.dongu}") # Beklenen: ['X']

# Test 6: Bağımlılık olmayan paket (D bağımlılıkta yok)
deps6 = {"A": [], "D": []}
sira6 = kurulum_sirasi(deps6)
print(f"Test 6 (A, D): {sira6}") # Beklenen: ['A', 'D']

